            {w:'Jan W3',n:2},{w:'Jan W4',n:3},{w:'Feb W1',n:1},{w:'Feb W2',n:4},
            {w:'Feb W3',n:3},{w:'Feb W4',n:2},{w:'Mar W1',n:5},{w:'Mar W2',n:4},
            {w:'Mar W3',n:3},{w:'Mar W4',n:6},{w:'Apr W1',n:4},{w:'Apr W2',n:3}
